    const errors={draft_base_changed:'Действующий график изменился. Создайте новый черновик на актуальной основе; этот сохранён для сравнения.',draft_version_conflict:'Черновик уже изменён. Закройте окно и откройте актуальную версию.',draft_closed:'Черновик уже закрыт.',planning_conflict:'Есть пересечения или недоступные сотрудники. Исправьте предложения и повторите проверку.',planning_preview_changed:'Предпросмотр устарел. Выполните проверку ещё раз.',schedule_publish_forbidden:'Владелец не выдал право публикации.',planning_operations_limit:'Допускается не более 200 изменений. Уменьшите период или число сотрудников.',template_version_conflict:'Шаблон изменился. Откройте актуальную версию.',planning_pattern_invalid:'Проверьте дни повторения, дату начала цикла и его длину.',planning_slot_invalid:'Проверьте время, следующий день, функцию и перерыв.',planning_scope_invalid:'Дата или сотрудник вне области черновика.',planning_template_member_invalid:'Выбранный сотрудник не входит в этот шаблон состава.',schedule_range_invalid:'Период должен составлять от 1 до 93 дней.',planning_name_invalid:'Укажите название длиной до 120 символов.',planning_users_invalid:'Выберите от 1 до 100 сотрудников.',planning_timezone_changed:'Часовой пояс изменился. Создайте новый черновик.',schedule_past_reason_required:'Для изменения прошлого периода укажите причину.',schedule_settings_forbidden:'Владелец не выдал право настройки графика.',schedule_function_name_conflict:'Функция с таким названием уже существует.',schedule_employee_function_required:'Сотрудник не назначен на выбранную активную функцию.',schedule_availability_unavailable:'Смена попадает на интервал недоступности.',schedule_availability_outside_window:'Смена выходит за заданное окно доступности.',schedule_preferred_availability_mismatch:'Смена выходит за предпочтительное окно.',planning_warnings_confirmation_required:'Подтвердите предупреждения и укажите причину.'};
    Object.assign(errors,{schedule_reason_required:'Укажите причину отмены или изменения прошлого периода.',planning_empty:'В черновике нет изменений для публикации.',schedule_copy_time_ambiguous:'При повторении встретилось неоднозначное или несуществующее местное время из-за перевода часов. Измените время или период.',schedule_overlap:'Пересекающиеся смены или отсутствие',schedule_employee_unavailable:'Сотрудник недоступен для назначения',schedule_availability_invalid:'Проверьте доступность: число правил, время, тип и примечание.',schedule_availability_interval_invalid:'Укажите правильный интервал и отметьте переход на следующий день.',schedule_availability_date_invalid:'Проверьте дату исключения.',schedule_availability_rule_invalid:'Проверьте день недели и период действия правила.',schedule_availability_time_invalid:'Невозможно однозначно преобразовать местное время для этого дня.',schedule_availability_version_conflict:'Настройки доступности изменились. Перезагрузите их перед сохранением.',schedule_availability_unavailable:'Смена попадает на интервал недоступности.',schedule_availability_outside_window:'Смена выходит за доступное окно.',planning_warnings_confirmation_required:'Подтвердите предупреждение и укажите причину.'});
    Object.assign(errors,{schedule_venue_policy_version_conflict:'Правила заведения изменились. Обновите настройки и повторите сохранение.',schedule_venue_policy_threshold_invalid:'Проверьте порог правила. Значение должно быть целым числом в допустимом диапазоне или отключено.',schedule_venue_policy_interval_invalid:'Проверьте день недели и время интервала. Для ночного интервала выберите окончание на следующий день.',schedule_venue_policy_interval_duplicate:'Одинаковый рабочий интервал уже указан.',schedule_venue_policy_input_invalid:'Проверьте все поля правил заведения.',schedule_demand_timezone_changed:'Часовой пояс заведения изменился: потребность не пересчитывается до повторного сохранения правил.'});
    Object.assign(errors,{schedule_max_weekly_minutes:'Превышен ориентир недельной нагрузки.',schedule_minimum_rest:'Промежуток отдыха меньше настроенного ориентира.',schedule_max_consecutive_days:'Слишком много рабочих дат подряд по настройке заведения.',schedule_outside_business_hours:'Смена полностью не помещается в часы работы заведения.',schedule_business_hours_unverifiable:'Не удалось однозначно проверить часы работы из-за перехода времени.',schedule_demand_timezone_changed:'Часовой пояс заведения изменился. Подтвердите и сохраните правила потребности заново.',schedule_demand_overlap:'Интервал потребности пересекается с другим правилом того же уровня.',schedule_coverage_break_unknown:'Положение перерыва не задано: покрытие на этом интервале нельзя подтвердить.',schedule_coverage_deficit:'Недостаточное покрытие.',schedule_coverage_surplus:'Сотрудников больше, чем требуется.',schedule_coverage_double_assigned:'Сотрудник одновременно указан на разных функциях и не засчитан.',schedule_coverage_time_unverifiable:'Не удалось однозначно проверить местное время покрытия.',schedule_break_intervals_invalid:'Проверьте границы и отсутствие пересечения интервалов перерыва.',schedule_break_intervals_mismatch:'Сумма перерывов должна совпадать с указанным числом минут.',schedule_open_shift_function_required:'Для свободной смены укажите рабочую функцию.'});
    const api=async(...args)=>{try{return await request(...args);}catch(error){error.message=errors[error.code]||error.message;throw error;}};
    const name=id=>id?employees.find(p=>p.id===id)?.name||'Сотрудник недоступен':'Свободная смена';
