        async function loadBindings(){const area=d.node.querySelector('[data-bindings]');area.textContent='Загрузка привязок…';try{const [result,rolesResult,functionsResult]=await Promise.all([api('/template-bindings?includeInactive=true&includeArchived=true'),api('/role-options'),api('/functions')]);if(!dialogIsOpen(d))return;const roleNames=new Map(rolesResult.items.map(role=>[role.key,role.name])),functionNames=new Map(functionsResult.items.map(fn=>[fn.id,fn.name]));area.innerHTML=result.items.map(item=>{const target=item.targetKind==='employee'?`Сотрудник · ${name(item.targetUserId)}`:item.targetKind==='crm_role'?`Роль · ${roleNames.get(item.targetRoleKey)||item.targetRoleKey}`:`Функция · ${functionNames.get(item.targetFunctionId)||'Недоступна'}`;return `<button type="button" class="planning-list-item" data-binding="${esc(item.id)}"><strong>${esc(item.templateName)}</strong><span>${esc(target)} · приоритет ${item.priority} · версия ${item.version}${!item.active?' · архив':''}${item.templateArchived?' · шаблон в архиве':''}</span></button>`;}).join('')||'<p>Привязок пока нет. Создайте первую, чтобы ускорить выбор шаблона в календаре.</p>';area.querySelectorAll('[data-binding]').forEach(button=>button.onclick=()=>editBinding(result.items.find(item=>item.id===button.dataset.binding),loadBindings,d));}catch(error){if(dialogIsOpen(d)){area.textContent='Не удалось загрузить привязки. Нажмите «Обновить». ';d.error(error.message);}}}
